            if materia not in grupos:
                grupos[materia] = []
            grupos[materia].append(fila)
    return grupos

def promedio_por_materia(filas):
    """
    Calcula el promedio de las notas para cada materia.

    Args:
        filas: Lista de diccionarios, cada uno con 'alumno', 'materia' y 'nota'.

    Returns:
        Dict[str, float]: Diccionario donde la clave es la materia y el valor es su promedio.
    """
    materia_notas = {}
    for fila in filas:
        materia = fila['materia']
        nota = fila['nota']

        if materia not in materia_notas:
            materia_notas[materia] = {'suma': 0.0, 'cantidad': 0}

        materia_notas[materia]['suma'] += nota
        materia_notas[materia]['cantidad'] += 1

    promedios = {}
    for materia, datos in materia_notas.items():
        promedio = datos['suma'] / datos['cantidad']
        promedios[materia] = promedio

    return promedios

def aprobados(filas, corte):
    alumnos_aprobados = set()
    for fila in filas:
        if fila['nota'] >= corte:
            alumnos_aprobados.add(fila['alumno'])
    return sorted(list(alumnos_aprobados))

def alumnos(filas):
    """
    Recibe una lista de dicts con clave 'alumno'. Devuelve la lista de alumnos distintos, ordenada alfabéticamente.
    """
    if not filas:
        return []

    alumnos_unicos = set()
    for fila in filas:
        if 'alumno' in fila and isinstance(fila['alumno'], str):
            alumnos_unicos.add(fila['alumno'])

    return sorted(list(alumnos_unicos))

def formatear_nota(nota):
    return f"{nota:.2f}"

def resumen(filas):
    """
    Calcula un resumen estadístico de las notas.

    Args:
        filas: Lista de diccionarios, cada uno con 'alumno' (str), 
               'materia' (str) y 'nota' (float).

    Returns:
        dict: Contiene 'filas' (cantidad de filas), 'alumnos' (cantidad de alumnos distintos) 
              y 'promedio' (promedio de todas las notas).
    """
    num_filas = len(filas)

    if not filas:
        return {
            'filas': 0,
            'alumnos': 0,
            'promedio': 0.0
        }

    alumnos_distintos = set()
    suma_notas = 0.0

    for fila in filas:
        alumnos_distintos.add(fila['alumno'])
        suma_notas += fila['nota']

    cantidad_alumnos = len(alumnos_distintos)
    promedio_total = suma_notas / num_filas

    return {
        'filas': num_filas,
        'alumnos': cantidad_alumnos,
        'promedio': promedio_total
    }
